{
"predictors": 
[
  {
    "name": "CEO Tenure", 
    "construction": "Calculate the number of years since the current CEO took the position.", 
    "rationale": "CEOs with longer tenures may have more experience and knowledge about the company and industry, potentially leading to better performance.", 
    "higher_returns_for": "Longer CEO tenure"
  },
  {
    "name": "Environmental Impact Score", 
    "construction": "Quantify a firm's environmental impact based on publicly available reports and third-party evaluations.", 
    "rationale": "Firms that prioritize environmental sustainability may attract more socially responsible investors, potentially driving up stock price.", 
    "higher_returns_for": "Lower environmental impact"
  },
  {
    "name": "Diversity Index", 
    "construction": "Compute a diversity score based on employee demographic data disclosed in company reports.", 
    "rationale": "Diverse firms may benefit from varied perspectives and be more innovative, leading to better performance.", 
    "higher_returns_for": "Higher diversity index"
  },
  {
    "name": "Cybersecurity Investment", 
    "construction": "Measure investment in cybersecurity as a portion of total expenditure from annual financial statements.", 
    "rationale": "Companies prioritizing cybersecurity may be less likely to suffer from damaging breaches, protecting their brand and bottom line.", 
    "higher_returns_for": "Higher investment in cybersecurity"
  },
  {
    "name": "Employee Satisfaction", 
    "construction": "Aggregate employee reviews from online platforms like Glassdoor.", 
    "rationale": "Satisfied employees might be more productive and loyal, contributing to a stronger business.", 
    "higher_returns_for": "Higher employee satisfaction"
  },
  {
    "name": "Customer Satisfaction", 
    "construction": "Aggregate customer reviews from online platforms.", 
    "rationale": "Satisfied customers may increase sales through repeat purchases and referrals.", 
    "higher_returns_for": "Higher customer satisfaction"
  },
  {
    "name": "Social Media Sentiment", 
    "construction": "Use natural language processing to analyze sentiment about the company on social media platforms.", 
    "rationale": "Positive sentiment may indicate strong brand recognition and loyalty, potentially driving sales.", 
    "higher_returns_for": "Positive social media sentiment"
  },
  {
    "name": "Data Breach Occurrence", 
    "construction": "Track incidents of data breaches and consequent regulatory fines.", 
    "rationale": "Firms with past data breaches might underperform due to the costs of the breach and damaged reputation.", 
    "higher_returns_for": "No history of data breaches"
  },
  {
    "name": "Product Recalls", 
    "construction": "Count the number of product recalls from company and regulatory reports.", 
    "rationale": "Frequent product recalls may indicate quality control issues which may lead to financial losses and reputation damage.", 
    "higher_returns_for": "Fewer product recalls"
  },
  {
    "name": "Research and Development Intensity", 
    "construction": "Calculate R&D expenditure as a percentage of sales.", 
    "rationale": "Higher R&D intensity may indicate future growth opportunities.", 
    "higher_returns_for": "Higher R&D intensity"
  }
]
}
